{{ config(
            materialized='table',
                post_hook={
                    "sql": "delete FROM datalake_db.beardo._airbyte_raw_beardo_hourly_facebook_customcampaigns_data WHERE _airbyte_data:date_start::STRING::DATE > CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE - 2 ; CREATE OR REPLACE TABLE prd_db.beardo.Custom_Facebook_Marketing_Beardo_hourly_customcampaigns_data AS SELECT _airbyte_data:ad_id::STRING AS ad_id, _airbyte_data:ad_name::STRING AS ad_name, _airbyte_data:adset_id::STRING AS adset_id, _airbyte_data:adset_name::STRING AS adset_name, _airbyte_data:campaign_id::STRING AS campaign_id, _airbyte_data:campaign_name::STRING AS campaign_name, _airbyte_data:account_id::STRING AS account_id, _airbyte_data:account_name::STRING AS account_name, _airbyte_data:account_currency::STRING AS account_currency, _airbyte_data:objective::STRING AS objective, _airbyte_data:optimization_goal::STRING AS optimization_goal, _airbyte_data:quality_ranking::STRING AS quality_ranking, TRY_CAST(_airbyte_data:date_start::STRING AS DATE) AS date_start, TRY_CAST(_airbyte_data:date_stop::STRING AS DATE) AS date_stop, _airbyte_data:hourly_stats_aggregated_by_advertiser_time_zone::STRING AS hour, TRY_CAST(_airbyte_data:reach::STRING AS FLOAT) AS reach, TRY_CAST(_airbyte_data:spend::STRING AS FLOAT) AS spend, TRY_CAST(_airbyte_data:clicks::STRING AS INTEGER) AS clicks, TRY_CAST(_airbyte_data:impressions::STRING AS INTEGER) AS impressions, TRY_CAST(_airbyte_data:frequency::STRING AS FLOAT) AS frequency, TRY_CAST(_airbyte_data:inline_link_clicks::STRING AS INTEGER) AS inline_link_clicks, TRY_CAST(_airbyte_data:inline_post_engagement::STRING AS INTEGER) AS inline_post_engagement, _airbyte_data:actions AS actions, _airbyte_data:conversions AS conversions, _airbyte_data:action_values AS action_values, _airbyte_data:conversion_values AS conversion_values, _airbyte_data:outbound_clicks AS outbound_clicks, _airbyte_data:purchase_roas AS purchase_roas, _airbyte_data:website_purchase_roas AS website_purchase_roas FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY _airbyte_data:ad_id::STRING, TRY_CAST(_airbyte_data:date_start::STRING AS DATE), _airbyte_data:hourly_stats_aggregated_by_advertiser_time_zone::STRING ORDER BY _airbyte_emitted_at DESC ) AS rw FROM datalake_db.beardo._airbyte_raw_beardo_hourly_facebook_customcampaigns_data ) WHERE rw = 1; CREATE OR REPLACE TABLE prd_db.beardo.dwh_FACEBOOK_CONSOLIDATED_hourly AS select Adset_Name ,Adset_ID ,FB.ad_id ,FB.ad_name ,Account_Name ,Account_ID ,Campaign_Name ,Campaign_ID ,Fb.date_start::date Date ,sum(ifnull(inline_link_clicks,0)) Link_Clicks ,SUM(CLICKS) Clicks ,SUM(SPEND) Spend ,SUM(IMPRESSIONS) Impressions ,SUM(NVL(Fc.Conversions,0)) Conversions ,SUM(NVL(Fcv.Conversion_Value,0)) Conversion_Value ,sum(nvl(fd.add_to_carts,0)) Add_to_carts ,sum(nvl(fdv.add_to_cart_value,0)) Add_to_cart_value ,sum(nvl(fe.landing_page_views,0)) Landing_page_views ,sum(nvl(ff.initiate_checkouts,0)) Initiate_checkouts ,sum(nvl(ffv.initiate_checkouts_value,0)) Initiate_checkouts_value ,\'Facebook\' Channel ,\'Facebook India\' Account from prd_db.beardo.Custom_Facebook_Marketing_Beardo_hourly_customcampaigns_data FB left join ( select ad_id ,ad_name ,date_start ,SUM(C.value:value) Conversions from prd_db.beardo.Custom_Facebook_Marketing_Beardo_hourly_customcampaigns_data,lateral flatten(input => ACTIONS) C where C.value:action_type=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start having SUM(C.value:value) is not null )Fc ON Fb.ad_id = Fc.ad_id and Fb.date_start=Fc.date_start left join ( select ad_id ,ad_name ,date_start ,SUM(CV.value:\"1d_click\") Conversion_Value from prd_db.beardo.Custom_Facebook_Marketing_Beardo_hourly_customcampaigns_data,lateral flatten(input => ACTION_VALUES) CV where CV.value:action_type=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start having SUM(CV.value:value) is not null )Fcv ON Fb.ad_id = Fcv.ad_id and Fb.date_start=Fcv.date_start left join ( select ad_id ,date_start ,SUM(C.value:value) add_to_carts from prd_db.beardo.Custom_Facebook_Marketing_Beardo_hourly_customcampaigns_data,lateral flatten(input => ACTIONS) C where C.value:action_type=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(C.value:value) is not null )Fd ON Fb.ad_id = Fd.ad_id and Fb.date_start=Fd.date_start left join ( select ad_id ,date_start ,SUM(CV.value:value) Add_to_cart_Value from prd_db.beardo.Custom_Facebook_Marketing_Beardo_hourly_customcampaigns_data,lateral flatten(input => ACTION_VALUES) CV where CV.value:action_type=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(CV.value:value) is not null )Fdv ON Fb.ad_id = Fdv.ad_id and Fb.date_start=Fdv.date_start left join ( select ad_id ,date_start ,SUM(C.value:value) Landing_page_views from prd_db.beardo.Custom_Facebook_Marketing_Beardo_hourly_customcampaigns_data,lateral flatten(input => ACTIONS) C where C.value:action_type=\'landing_page_view\' group by ad_id,date_start having SUM(C.value:value) is not null )Fe ON Fb.ad_id = Fe.ad_id and Fb.date_start=Fe.date_start left join ( select ad_id ,date_start ,SUM(C.value:value) Initiate_checkouts from prd_db.beardo.Custom_Facebook_Marketing_Beardo_hourly_customcampaigns_data,lateral flatten(input => ACTIONS) C where C.value:action_type=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(C.value:value) is not null )Ff ON Fb.ad_id = Ff.ad_id and Fb.date_start=Ff.date_start left join ( select ad_id ,date_start ,SUM(CV.value:value) Initiate_checkouts_Value from prd_db.beardo.Custom_Facebook_Marketing_Beardo_hourly_customcampaigns_data,lateral flatten(input => ACTION_VALUES) CV where CV.value:action_type=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(CV.value:value) is not null )Ffv ON Fb.ad_id = Ffv.ad_id and Fb.date_start=Ffv.date_start where fb.date_start >= \'2024-08-13\' group by Adset_Name, Adset_ID,fb.ad_id,fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID,Fb.date_start ; CREATE OR REPLACE TABLE prd_db.Beardo.dwh_MARKETING_CONSOLIDATED AS select * from ( select ACCOUNT_NAME ,ACCOUNT_ID ,CAMPAIGN_NAME ,CAMPAIGN_ID ,ADSET_NAME ,ADSET_ID ,AD_ID ,AD_NAME ,DATE ,NULL AD_TYPE ,NULL AD_STRENGTH ,NULL AD_NETWORK_TYPE ,NULL AD_URL ,dayofweek(DATE)::string Day_of_Week ,YEAR(DATE) AS YEAR1 ,MONTH(DATE) AS MONTH1 ,CHANNEL ,ACCOUNT ,Clicks ,Link_Clicks ,Spend ,Impressions ,Conversions ,Conversion_Value ,Add_to_carts ,Add_to_cart_value ,Landing_page_views ,Initiate_checkouts ,Initiate_checkouts_value ,case when lower(campaign_name) like \'%branding%\' then \'Branding\' when lower(campaign_name) like \'%performance%\' then \'Performance\' end as branding_campaign from prd_db.Beardo.DWH_FACEBOOK_CONSOLIDATED where date < current_date union select ACCOUNT_NAME ,ACCOUNT_ID ,CAMPAIGN_NAME ,CAMPAIGN_ID ,ADSET_NAME ,ADSET_ID ,AD_ID ,AD_NAME ,DATE ,NULL AD_TYPE ,NULL AD_STRENGTH ,NULL AD_NETWORK_TYPE ,NULL AD_URL ,dayofweek(DATE)::string Day_of_Week ,YEAR(DATE) AS YEAR1 ,MONTH(DATE) AS MONTH1 ,CHANNEL ,ACCOUNT ,Clicks ,Link_Clicks ,Spend ,Impressions ,Conversions ,Conversion_Value ,Add_to_carts ,Add_to_cart_value ,Landing_page_views ,Initiate_checkouts ,Initiate_checkouts_value ,case when lower(campaign_name) like \'%branding%\' then \'Branding\' when lower(campaign_name) like \'%performance%\' then \'Performance\' end as branding_campaign from prd_db.Beardo.dwh_FACEBOOK_CONSOLIDATED_hourly where date = current_date union select ACCOUNT_NAME ,ACCOUNT_ID ,CAMPAIGN_NAME ,CAMPAIGN_ID ,ADSET_NAME ,ADSET_ID ,AD_ID ,AD_NAME ,Date ,AD_TYPE ,AD_STRENGTH ,AD_NETWORK_TYPE ,AD_FINAL_URL ,Day_of_Week ,YEAR ,MONTH ,Channel ,ACCOUNT ,clicks ,null as Link_Clicks ,spend ,impressions ,conversions ,Conversion_Value ,null as Add_to_carts ,null as Add_to_cart_value ,null as Landing_page_views ,null as Initiate_checkouts ,null as Initiate_checkouts_value ,case when lower(campaign_name) like \'%branding%\' then \'Branding\' when lower(campaign_name) like \'%performance%\' then \'Performance\' end as branding_campaign from prd_db.beardo.dwh_GOOGLEADS_CONSOLIDATED Union Select \'Amazon\' AS ACCOUNT_NAME ,PROFILEID ,CAMPAIGNNAME ,CAMPAIGNID ,adGroupName ,adGroupId ,ADID ,NULL AS AD_NAME ,DATE ,CAMPAIGN_TYPE ,NULL AS AD_STRENGTH ,NULL AS AD_NETWORK_TYPE ,NULL AS AD_URL ,dayofweek(DATE)::string DAY_OF_WEEK ,YEAR(DATE) YEAR1 ,MONTH(DATE) MONTH1 ,\'AMAZON\' AS CHANNEL ,NULL AS ACCOUNT ,sum(CLICKS) ,null as Link_Clicks ,sum(SPEND) ,sum(IMPRESSIONS) ,sum(CONVERSIONS) ,sum(AdSales) ,NULL AS ADD_TO_CARTS ,NULL AS ADD_TO_CART_VALUE ,NULL AS LANDING_PAGE_VIEWS ,null as Initiate_checkouts ,null as Initiate_checkouts_value ,case when lower(campaignname) like \'%branding%\' then \'Branding\' when lower(campaignname) like \'%performance%\' then \'Performance\' end as branding_campaign FROM prd_db.Beardo.dwh_AMAZONADS_MARKETING group by ACCOUNT_NAME ,PROFILEID ,CAMPAIGNNAME ,CAMPAIGNID ,adGroupName ,adGroupId ,ADID ,AD_NAME ,DATE ,CAMPAIGN_TYPE ,AD_STRENGTH ,AD_NETWORK_TYPE ,AD_URL ,DAYNAME(DATE) ,YEAR(DATE) ,MONTH(DATE) ,CHANNEL ,ACCOUNT ) where channel not in (\'AMAZON\') ; create or replace table prd_db.beardo.beardo_ad_creatives_fact_items as with video_metrics as ( select ad_id::string as ad_id, date_start::date Date, sum(f.value:value::int) as total_3_sec_views from beardo.custom_facebook_marketing_customad_video_metrics_data, lateral flatten(input => actions) f where f.value:action_type::string = \'video_view\' and date < current_date group by 1,2 union select ad_id::string as ad_id, date_start::date Date, sum(f.value:value::int) as total_3_sec_views from beardo.beardo_facebook_customad_video_metrics_data_hourly, lateral flatten(input => actions) f where f.value:action_type::string = \'video_view\' and date = current_date group by 1,2 ), thruplay_metrics AS ( SELECT ad_id::STRING AS ad_id, date_start::date Date, SUM(f.value:value::INT) AS total_thruplays FROM beardo.custom_facebook_marketing_customad_video_metrics_data, LATERAL FLATTEN(input => video_thruplay_watched_actions) f GROUP BY 1,2 ), landing_page_views as ( select concat(\'HTTPS://BEARDO.IN\', upper(landingpage)) as landingpage, to_date(date,\'YYYYMMDD\') as date, sum(cast(sessions as int)) as sessions, sum(cast(engagedsessions as int)) as engaged_sessions, sum(cast(addtocarts as int)) as add_to_carts from datalake_db.beardo.ga4_beardo_landing_page_funnel_metrics group by 1,2 ), marketing_data as ( select cast(cast(ad_id as int) as string) ad_id, regexp_replace(ad_name, \' +\', \' \') as ad_name, date, sum(SPEND) as amount_spend, sum(impressions) as impressions, sum(clicks) as clicks, sum(link_clicks) as link_clicks from prd_db.Beardo.dwh_MARKETING_CONSOLIDATED group by 1,2,3 ), shopify_sales as ( SELECT final_utm_content AS ad_id, landingpageurl AS landing_page_url, sku, product_name, DATE(order_timestamp) AS order_date, SUM(weighted_order_count) AS total_orders, SUM(IFNULL(line_item_sales,0)) - sum(ifnull(discount,0)) AS total_sales FROM ( SELECT *, 1 / COUNT(*) OVER (PARTITION BY order_name) AS weighted_order_count FROM prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS ) GROUP BY 1,2,3,4,5 ), joined_data AS ( SELECT COALESCE(m.ad_id, s.ad_id, v.ad_id) AS ad_id, COALESCE(m.date, s.order_date, v.date) AS date, m.ad_name, s.landing_page_url, s.sku, s.product_name, NVL(m.amount_spend, 0) AS raw_spend, NVL(m.impressions, 0) AS raw_impressions, NVL(m.clicks, 0) AS raw_clicks, NVL(m.link_clicks, 0) AS raw_link_clicks, NVL(v.total_3_sec_views, 0) AS raw_video_views, NVL(t.total_thruplays, 0) AS total_thruplays, NVL(s.total_orders, 0) AS total_orders, NVL(s.total_sales, 0) AS total_sales, NULLIF(COUNT(*) OVER (PARTITION BY COALESCE(m.ad_id, s.ad_id, v.ad_id), COALESCE(m.date, s.order_date)), 0) AS ad_divisor, NULLIF(COUNT(*) OVER (PARTITION BY s.landing_page_url, COALESCE(m.date, s.order_date)), 0) AS lp_divisor FROM marketing_data m FULL OUTER JOIN shopify_sales s ON m.ad_id = s.ad_id AND m.date = s.order_date LEFT JOIN video_metrics v ON v.ad_id = COALESCE(m.ad_id, s.ad_id) AND v.date = COALESCE(m.date, s.order_date) LEFT JOIN thruplay_metrics t ON t.ad_id = COALESCE(m.ad_id, s.ad_id) AND t.date = COALESCE(m.date, s.order_date) ) SELECT j.date, j.ad_id, j.ad_name, j.landing_page_url, j.sku, j.product_name, (j.raw_spend / j.ad_divisor) AS amount_spend, (j.raw_impressions / j.ad_divisor) AS impressions, (j.raw_clicks / j.ad_divisor) AS clicks, (j.raw_link_clicks / j.ad_divisor) AS link_clicks, (j.raw_video_views / j.ad_divisor) AS total_3_sec_views, (j.total_thruplays / j.ad_divisor) AS total_thruplays, j.total_orders, j.total_sales, (NVL(l.engaged_sessions, 0) / j.lp_divisor) AS engaged_sessions, (NVL(l.sessions, 0) / j.lp_divisor) AS sessions, (NVL(l.add_to_carts, 0) / j.lp_divisor) AS add_to_carts FROM joined_data j LEFT JOIN landing_page_views l ON LOWER(l.landingpage) = LOWER(j.landing_page_url) AND l.date = j.date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from PRD_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            